// Writes src/app/version.ts from package.json before every `npm start` / `npm run build` (npm pre-scripts), so the
// sidebar shows the running version. The generated file is git-ignored — never edit it by hand; bump the number
// with `npm version patch|minor|major --no-git-tag-version`.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const { version } = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));

writeFileSync(
  join(root, 'src/app/version.ts'),
  `// Generated by scripts/write-version.mjs at build time — do not edit (git-ignored).\n` +
    `export const APP_VERSION = '${version}';\n`,
);
console.log(`version.ts → v${version}`);
